    "സവിശേഷതകൾ, പേജുകൾ, അല്ലെങ്കിൽ കമാൻഡുകൾ എക്സിക്യൂട്ട് ചെയ്യുന്നതിനായി കമാൻഡ് പാലറ്റ് തുറക്കുക",
  "shortcuts.vscode.title": "എല്ലാ കമാൻഡുകളും കാണിക്കുക (കമാൻഡ് പാലറ്റ്)",
  "shortcuts.preset_sublime_desc": "മികച്ച ടെക്‌സ്‌റ്റ് കീബൈൻഡിംഗുകൾ: Ctrl+Shift+P, Ctrl+P, Ctrl+K Ctrl+B, Ctrl+B",
  "shortcuts.preset_sublime_name": "ഉദാത്തമായ വാചകം",
  "shortcuts.preset_vim_desc": "Vim ശൈലി നാവിഗേഷൻ: സ്പേസ് സ്പേസ്, Ctrl+P, Ctrl+W V, Ctrl+W T, G Q",
  "shortcuts.preset_vim_name": "വിം സ്റ്റൈൽ",
  "shortcuts.preset_jetbrains_desc": "JetBrains കീബൈൻഡിംഗുകൾ: Ctrl+Shift+A, Ctrl+Shift+N, Alt+F12, Alt+1, Ctrl+Alt+S",
  "shortcuts.preset_jetbrains_name": "JetBrains / IntelliJ IDEA",
  "shortcuts.preset_vscode_desc": "ക്ലാസിക് VS കോഡ് കീബൈൻഡിംഗുകൾ: Ctrl+Shift+P, Ctrl+P, Ctrl+`, Ctrl+B",
  "shortcuts.preset_vscode_name": "വിഎസ് കോഡ് (സ്ഥിരസ്ഥിതി)",
  "cmdpalette.cmd_output_desc":
    "പശ്ചാത്തല ഇവൻ്റുകൾ, സിസ്റ്റം അറിയിപ്പുകൾ എന്നിവ പരിശോധിക്കുക, ഔട്ട്പുട്ടുകൾ നിർമ്മിക്കുക",
  "cmdpalette.cmd_output_title": "റൺടൈം ഔട്ട്പുട്ടും ലോഗുകളും കാണിക്കുക",
  "cmdpalette.cmd_new_terminal_desc": "താഴെയുള്ള ഡ്രോയറിൽ ഒരു പുതിയ ടെർമിനൽ ഷെൽ സെഷൻ സൃഷ്ടിക്കുക",
  "cmdpalette.cmd_new_terminal_title": "പുതിയ ടെർമിനൽ സെഷൻ സൃഷ്ടിക്കുക",
  "cmdpalette.cmd_terminal_desc": "താഴെയുള്ള ഡ്രോയർ സംയോജിത ഷെൽ സെഷൻ വെളിപ്പെടുത്തുക അല്ലെങ്കിൽ ടോഗിൾ ചെയ്യുക",
  "cmdpalette.cmd_terminal_title": "ഇൻ്റഗ്രേറ്റഡ് ടെർമിനൽ (ടെർമിനൽ) ടോഗിൾ ചെയ്യുക",
  "cmdpalette.cmd_scope_desc": "വർക്ക്‌സ്‌പെയ്‌സിനും ആഗോള ~/.unirtm നും ഇടയിലുള്ള സജീവ കോൺഫിഗറേഷൻ ടോഗിൾ ചെയ്യുക",
  "cmdpalette.cmd_scope_title": "സ്കോപ്പ് മാറ്റുക (വർക്ക്‌സ്‌പേസ് / ഉപയോക്തൃ ഗ്ലോബൽ)",
  "cmdpalette.cmd_theme_desc": "ഉയർന്ന കോൺട്രാസ്റ്റ് ഡാർക്ക് മോഡും ക്ലീൻ ലൈറ്റ് തീമും തമ്മിൽ ടോഗിൾ ചെയ്യുക",
  "cmdpalette.cmd_theme_title": "ലൈറ്റ് / ഡാർക്ക് അപ്പിയറൻസ് മോഡ് ടോഗിൾ ചെയ്യുക",
  "cmdpalette.cmd_shortcuts_desc": "VS കോഡുമായി വിന്യസിച്ചിരിക്കുന്ന കീബോർഡ് കുറുക്കുവഴികളുടെ പൂർണ്ണമായ ലിസ്റ്റ് കാണുക",
  "cmdpalette.cmd_shortcuts_title": "കീബോർഡ് കുറുക്കുവഴി റഫറൻസ് (VS കോഡ് വിന്യസിച്ചു)",
  "cmdpalette.cmd_about_desc": "പതിപ്പ് ബിൽഡ് വിവരം, ലൈസൻസ് വിവരങ്ങൾ, ചേഞ്ച്ലോഗ് എന്നിവ കാണുക",
  "cmdpalette.cmd_about_title": "UniRTM-നെ കുറിച്ച് (ഏകദേശം)",
  "cmdpalette.cmd_settings_desc":
    "തീമുകൾ, നെറ്റ്‌വർക്ക് പ്രോക്സികൾ, യാന്ത്രിക അപ്‌ഡേറ്റ്, സുരക്ഷാ കീകൾ എന്നിവ കോൺഫിഗർ ചെയ്യുക",
  "cmdpalette.cmd_settings_title": "മുൻഗണനകളും ക്രമീകരണങ്ങളും (ക്രമീകരണങ്ങൾ)",
  "cmdpalette.cmd_environments_desc":
    "വർക്ക്‌സ്‌പെയ്‌സും ഉപയോക്തൃ ആഗോള പരിസ്ഥിതി വേരിയബിളുകളും കോൺഫിഗർ ചെയ്യുകയും നിയന്ത്രിക്കുകയും ചെയ്യുക",
  "cmdpalette.cmd_environments_title": "പരിസ്ഥിതി വേരിയബിളുകൾ (പരിസ്ഥിതികൾ)",
  "cmdpalette.cmd_tasks_desc": "ഒറ്റ-ക്ലിക്ക് ബിൽഡ്, ടെസ്റ്റ്, ലിൻ്റ്, വർക്ക്ഫ്ലോ പൈപ്പ്ലൈൻ ടാസ്ക്കുകൾ",
  "cmdpalette.cmd_tasks_title": "പ്രോജക്റ്റ് ഓട്ടോമേഷൻ ടാസ്‌ക്കുകൾ (ടാസ്‌ക്കുകൾ)",
  "cmdpalette.cmd_tools_desc": "Node.js, പൈത്തൺ, ഗോ, റസ്റ്റ്, റൺടൈം പതിപ്പുകൾ വേഗത്തിൽ നിയന്ത്രിക്കുക",
  "cmdpalette.cmd_tools_title": "ടൂൾചെയിനുകളും പ്രവർത്തന സമയവും (ടൂളുകൾ)",
  "cmdpalette.cmd_guard_desc":
    "സുരക്ഷാ സ്കാനിംഗ്, ലീക്ക് ഇൻ്റർസെപ്ഷൻ, ഫോർമാറ്റ് കംപ്ലയൻസ് എന്നിവ മുൻകൂട്ടി കമ്മിറ്റ് ചെയ്യുക",
  "cmdpalette.cmd_guard_title": "ക്വാളിറ്റി ഗാർഡ് ഹാർനെസ് (ഗാർഡ്)",
  "cmdpalette.cmd_dashboard_desc": "UniRTM പ്രോജക്റ്റ് സ്റ്റാറ്റസ് അവലോകനം, റൺടൈം മെട്രിക്‌സ്, ദ്രുത പ്രവർത്തനങ്ങൾ",
  "cmdpalette.cmd_dashboard_title": "പ്രോജക്റ്റ് അവലോകന ഡാഷ്ബോർഡ് (ഡാഷ്ബോർഡ്)",
  "cmdpalette.cmd_marketplace_desc":
    "തീമുകൾ, പ്ലഗിനുകൾ, ഇക്കോസിസ്റ്റം വിപുലീകരണങ്ങൾ എന്നിവ കണ്ടെത്തി ഇൻസ്റ്റാൾ ചെയ്യുക",
  "cmdpalette.cmd_marketplace_title": "എക്സ്റ്റൻഷൻ മാർക്കറ്റ്പ്ലേസ് (മാർക്കറ്റ്പ്ലേസ്)",
  "cmdpalette.cmd_doctor_desc": "കോർ റൺടൈമുകൾ, ഷിംസ് റൂട്ടിംഗ്, ഡിസ്ക് കാൽപ്പാടുകൾ, API ക്വാട്ടകൾ എന്നിവ അന്വേഷിക്കുക",
  "cmdpalette.cmd_doctor_title": "സിസ്റ്റം ഹെൽത്ത് ഡയഗ്നോസിസ് (ഡോക്ടർ)",
  "cmdpalette.cmd_scm_desc": "മാറ്റങ്ങൾ, സ്റ്റേജ് ഫയലുകൾ, ബ്രാഞ്ചുകൾ മാറുക, git കമ്മിറ്റ് ഗ്രാഫുകൾ കാണുക",
  "cmdpalette.cmd_scm_title": "ഉറവിട നിയന്ത്രണം (SCM / Git)",
  "cmdpalette.cmd_explorer_desc": "വർക്ക്‌സ്‌പെയ്‌സ് ഡയറക്‌ടറികൾ ബ്രൗസ് ചെയ്‌ത് എഡിറ്റർ ഫയലുകൾ കാണുക",
  "cmdpalette.cmd_explorer_title": "ഫയൽ എക്സ്പ്ലോറർ (എക്സ്പ്ലോറർ)",
