  "settings.profile_china_desc":
    "ദ്രുതഗതിയിലുള്ള പ്രീ-ബിൽഡ് ഡിപൻഡൻസി ഡൗൺലോഡുകൾക്കായി മുൻനിര ചൈനീസ് സർവകലാശാലകളിൽ നിന്നും ക്ലൗഡ് ദാതാക്കളിൽ നിന്നുമുള്ള പൊതു മിറർ മാട്രിക്സ്",
