  "runtimes.empty_workspace_desc":
    "വർക്ക്‌സ്‌പെയ്‌സ് കോൺഫിഗറേഷനിൽ (.unirtm.toml) ഉപകരണങ്ങളൊന്നും കോൺഫിഗർ ചെയ്തിട്ടില്ല. ചേർക്കാൻ മുകളിലുള്ള '+ ആഡ് റൺടൈം' ഉപയോഗിക്കുക.",
  "runtimes.empty_user_desc":
    "ഉപയോക്തൃ പ്രൊഫൈൽ കോൺഫിഗറേഷൻ (~/.config/unirtm/unirtm.toml) ഏതെങ്കിലും വർക്ക്‌സ്‌പെയ്‌സുമായി അറ്റാച്ച് ചെയ്യപ്പെടാത്തപ്പോൾ ആഗോള ഫാൾബാക്ക് പരിതസ്ഥിതികൾ നൽകുന്നു. കോൺഫിഗർ ചെയ്യുന്നതിന് മുകളിലുള്ള '+ ആഡ് റൺടൈം' ഉപയോഗിക്കുക.",
  "runtimes.empty_workspace_title": "നിലവിലെ വർക്ക്‌സ്‌പെയ്‌സിൽ ഉപകരണങ്ങളൊന്നും കോൺഫിഗർ ചെയ്‌തിട്ടില്ല",
  "runtimes.empty_user_title": "ഉപയോക്തൃ പ്രൊഫൈലിൽ ഉപകരണങ്ങളൊന്നും കോൺഫിഗർ ചെയ്തിട്ടില്ല",
