  "privilege.reason_desc":
    "നേരിട്ടുള്ള ഹാർഡ്‌വെയർ, റോ സ്റ്റോറേജ്, ലോ-ലെവൽ സിസ്റ്റം കോൺഫിഗറേഷൻ ആക്‌സസ് എന്നിവ ഓപ്പറേറ്റിംഗ് സിസ്റ്റങ്ങൾ നിയന്ത്രിക്കുന്നു. അംഗീകാരം സുരക്ഷിതമായ സ്കോപ്പ്ഡ് ആക്സസ് നൽകുന്നു.",
